namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and he holds patents in distributed computing." },
        new() { Id = 3, DepartmentId = 1, Code = "CS 350", Title = "Software Engineering", Description = "Principles of software design, development methodologies, version control, testing, and team collaboration.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez spent 10 years in industry at major tech companies before joining academia.", IsFeatured = true },
        new() { Id = 4, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students." },
        new() { Id = 5, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang's research spans applied linear algebra and numerical methods.", IsFeatured = true },
        new() { Id = 6, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Fri Lab", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a former NASA researcher with expertise in classical mechanics." },
        new() { Id = 7, DepartmentId = 3, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, and quantum measurement.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Priya Patel", InstructorBio = "Dr. Patel's research in quantum information has been published in Nature and Physical Review Letters.", IsFeatured = true },
        new() { Id = 8, DepartmentId = 4, Code = "ENG 110", Title = "Academic Writing", Description = "Develop skills in critical reading, argumentation, and academic essay writing.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Prof. David Turner", InstructorBio = "Prof. Turner is a published author and has taught writing workshops internationally." },
        new() { Id = 9, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of major works in American literature from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Lisa Monroe", InstructorBio = "Dr. Monroe specializes in 20th-century American fiction and has authored three critical studies." },
        new() { Id = 10, DepartmentId = 5, Code = "BIO 101", Title = "Introduction to Biology", Description = "Foundational concepts in cell biology, genetics, evolution, and ecology.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab", InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor's research focuses on molecular genetics and he mentors undergraduate researchers.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }
}

